"use client";

import { useEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

export function ScrollProgress() {
  const progressRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    gsap.registerPlugin(ScrollTrigger);

    const progressElement = progressRef.current;
    if (!progressElement) return;

    const setProgress = gsap.quickSetter(
      progressElement,
      "scaleX",
    ) as (value: number) => void;

    const trigger = ScrollTrigger.create({
      start: 0,
      end: () => ScrollTrigger.maxScroll(window),
      onUpdate: ({ progress }) => {
        setProgress(progress);
        progressElement.setAttribute(
          "aria-valuenow",
          Math.round(progress * 100).toString(),
        );
      },
    });

    return () => trigger.kill();
  }, []);

  return (
    <div className="pointer-events-none fixed inset-x-0 top-0 z-[9999] h-1 bg-black/10">
      <div
        ref={progressRef}
        role="progressbar"
        aria-label="Progreso de lectura"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={0}
        className="h-full origin-left scale-x-0 bg-emerald-400 will-change-transform"
      />
    </div>
  );
}
```

Móntalo una sola vez en el `layout.tsx`. La escala se modifica directamente desde `onUpdate`, evitando un render de React en cada evento de scroll.
